define(
    [
        'jquery',
        "jquery/ui",
        'Bss_CABAV/js/owl.carousel.min'
    ],
    function ($) {
        return function (config, element) {
            $(element).owlCarousel({
                loop: false,
                rewind: true,
                margin: 10,
                nav: true,
                responsive: {
                    0: {
                        items: 1
                    },
                    600: {
                        items: 3
                    },
                    1000: {
                        items: config.max
                    }
                }
            })
        }
    }
);
